mapper.select:
select a.*, esf.voucher_status from eg_service_fee_details_new a left join eg_service_fee_new esf on a.service_fee_id = esf.id where a.del_flag = '0' and (a.should_apportionment_amount_no_tax <> 0 or a.accrued_amount <> 0) and a.special_status_adjustment_flag = '0'
and a.service_fee_id = #{param.serviceFeeId}
and a.service_fee_id in
#{item}
and a.contract_code like concat('%', #{param.contractCode}, '%')
and a.contract_status = #{param.contractStatus}

select a.*,
ec.sharing_service_fee_flag shared_flag,
ec.end_sharing_service_fee_flag,
ec.special_status_adjustment_flag
from eg_service_fee_details_new a
left join eg_contract_month ec on a.contract_code = ec.contract_code and a.org_id =ec.org_id
left join eg_service_fee_new esf on a.service_fee_id = esf.id
where
1=1
and  a.should_apportionment_amount_no_tax <> 0
and ec.special_status_adjustment_flag = false

    and a.business_code in

        #{item}



    and a.allocation_method = #{param.allocationMethod}


    and a.allocation_completion_mark = #{param.allocationCompletionMark}


    and a.service_fee_id = #{param.serviceFeeId}


    and ec.contract_status = #{param.contractStatus}


    and ec.financial_contract_status = #{param.financialContractStatus}


    and a.is_generate_voucher = #{param.voucherStatus}


    and a.lease_date_start >= #{param.leaseDateStart}


    and a.lease_date_end <= #{param.leaseDateEnd}


    and a.business_date >= #{param.businessStartDate}


    and a.business_date <= #{param.businessEndDate}


    and a.contract_code like concat('%', #{param.contractCode}::text, '%')


    and a.org_id in

        #{item}



    and a.service_org_id in

        #{item}



    and a.service_fee_id in

        #{item}



    and a.exception_type in

        #{item}



    and ec.financial_contract_status in

        #{item}



    and ec.system_code in

        #{item}


order by a.contract_code ,a.service_fee_no ,a.periods

select * from eg_service_fee_details_new
where
accrual_year = #{preYearValue}
and accrual_month = #{preMonthValue}
and should_apportionment_amount_no_tax <> (accrued_amount + before_accrued_amount)

and contract_code not in

    #{item}

with t1 as (select service_fee_no, service_org_id from (select p.service_fee_no, p.service_org_id, sum(p.accrued_amount) accrued_amount_sum, max(p.should_apportionment_amount_no_tax) should_apportionment_amount_no_tax_max from eg_service_fee_plan_new p, (select service_fee_no, service_org_id, max(plan_date) max_plan_date from eg_service_fee_plan_new where del_flag = '0' group by service_fee_no, service_org_id) t where p.service_fee_no = t.service_fee_no and p.service_org_id = t.service_org_id and t.max_plan_date < #{date} group by p.service_fee_no, p.service_org_id) tt where tt.accrued_amount_sum <> tt.should_apportionment_amount_no_tax_max), t2 as (select d.service_org_id, d.service_fee_no, max(d.business_date) business_date from eg_service_fee_details_new d, t1 where d.service_org_id = t1.service_org_id and d.service_fee_no = t1.service_fee_no group by d.service_org_id, d.service_fee_no) select dd.* from eg_service_fee_details_new dd, (SELECT d1.service_org_id, d1.service_fee_no, max(d1.business_date) business_date FROM eg_service_fee_details_new d1, t2 where d1.service_org_id = t2.service_org_id and d1.service_fee_no = t2.service_fee_no and d1.del_flag = '0' group by d1.service_org_id, d1.service_fee_no) t3 where dd.service_org_id = t3.service_org_id and dd.service_fee_no = t3.service_fee_no and dd.business_date = t3.business_date and dd.del_flag = '0'
and dd.contract_code not in
#{item}
